const q = $json.query || $json;
const mode = q['hub.mode'] || '';
const token = q['hub.verify_token'] || '';
const challenge = q['hub.challenge'] || '';
let expected = 'llbox-whatsapp-verify';
try {
  const cfg = $('Config').first().json;
  if (cfg && cfg.verifyToken) expected = String(cfg.verifyToken);
} catch (e) {}
const ok = mode === 'subscribe' && token === expected;
return [{ json: { ok, challenge: String(challenge || ''), mode } }];

const input = $input.first().json || {};

const headers = input.headers || {};
const signatureHeader = String(
  headers['x-hub-signature-256'] ||
  headers['X-Hub-Signature-256'] ||
  ''
).trim();

let config = {};
try {
  config = $('Config').first().json || {};
} catch (_) {
  config = {};
}
const appSecret = String(config.metaAppSecret || input.metaAppSecret || '').trim();

let rawBody = input.rawBody;
if (typeof rawBody !== 'string') rawBody = input.bodyRaw;
if (typeof rawBody !== 'string') rawBody = JSON.stringify(input.body || {});

let signatureValid = false;
let signatureError = '';

if (!appSecret || appSecret === 'PASTE_YOUR_META_APP_SECRET') {
  signatureError = 'META_APP_SECRET_NOT_CONFIGURED';
} else if (!signatureHeader) {
  signatureError = 'MISSING_X_HUB_SIGNATURE_256';
} else if (!/^sha256=[a-f0-9]{64}$/i.test(signatureHeader)) {
  signatureError = 'INVALID_SIGNATURE_FORMAT';
} else {
  try {
    const crypto = require('crypto');
    const received = signatureHeader.slice(7).toLowerCase();
    const expected = crypto
      .createHmac('sha256', appSecret)
      .update(rawBody, 'utf8')
      .digest('hex');
    const a = Buffer.from(received, 'hex');
    const b = Buffer.from(expected, 'hex');
    signatureValid = a.length === b.length && crypto.timingSafeEqual(a, b);
    if (!signatureValid) signatureError = 'SIGNATURE_MISMATCH';
  } catch (_) {
    signatureError = 'CRYPTO_VERIFY_FAILED';
  }
}

return [{
  json: {
    ...input,
    signatureValid,
    signatureOk: signatureValid,
    signatureChecked: true,
    signatureError
  }
}];

const now = new Date();
const y = now.getUTCFullYear();
const m = String(now.getUTCMonth() + 1).padStart(2, '0');
const d = String(now.getUTCDate()).padStart(2, '0');
const rand = Math.random().toString(36).slice(2, 10).toUpperCase();
const correlationId = `LLB-WA-${y}${m}${d}-${rand}`;
const cfg = $('Config').item.json;
return [{ json: { ...$json, correlationId, receivedAt: now.toISOString(), workflowVersion: cfg.workflowVersion } }];

const raw = $('WhatsApp Webhook (POST)').item.json;
const corr = $json.correlationId;
const body = raw.body || raw;
const change = body?.entry?.[0]?.changes?.[0]?.value || {};
const message = Array.isArray(change.messages) ? change.messages[0] : null;
const statuses = Array.isArray(change.statuses) ? change.statuses : [];

if (!message && statuses.length) {
  return [{ json: { correlationId: corr, skip: true, isMessage: false, reason: 'delivery_status' } }];
}
if (!message) {
  return [{ json: { correlationId: corr, skip: true, isMessage: false, reason: 'no_message' } }];
}

const type = message.type || 'text';
const text = type === 'text'
  ? String(message.text?.body || '').trim()
  : String(message.image?.caption || message.document?.caption || message.video?.caption || '').trim();
const mediaId = message.audio?.id || message.image?.id || message.document?.id || message.video?.id || '';
const mimeType = message.audio?.mime_type || message.image?.mime_type || message.document?.mime_type || message.video?.mime_type || '';
const filename = message.document?.filename || '';

return [{ json: {
  correlationId: corr,
  skip: false,
  isMessage: true,
  inputType: type,
  messageType: type,
  phone: String(message.from || ''),
  text,
  messageText: text,
  caption: text,
  mediaId,
  mimeType,
  filename,
  messageId: message.id || '',
  waProfileName: change.contacts?.[0]?.profile?.name || '',
  phoneNumberId: change.metadata?.phone_number_id || '',
  waTimestamp: message.timestamp || '',
  reply_mode: type === 'audio' ? 'voice' : 'text'
} }];

// Uses n8n workflow static data as a lightweight store.
// NOTE: static data is per-workflow-instance. For multi-instance/HA n8n
// deployments, replace this with a shared store (Redis/Postgres) or a
// LLBox backend idempotency endpoint.
const staticData = $getWorkflowStaticData('global');
staticData.processedMessages = staticData.processedMessages || {};

const msgId = $json.messageId;
const now = Date.now();
const TTL_MS = 24 * 60 * 60 * 1000; // 24h

// Cleanup old entries opportunistically
for (const [id, ts] of Object.entries(staticData.processedMessages)) {
  if (now - ts > TTL_MS) delete staticData.processedMessages[id];
}

const alreadyProcessed = Boolean(staticData.processedMessages[msgId]);
if (!alreadyProcessed) {
  staticData.processedMessages[msgId] = now;
}

return [{ json: { ...$json, alreadyProcessed } }];

const staticData = $getWorkflowStaticData('global');
staticData.rateWindows = staticData.rateWindows || {};
const cfg = $('Config').item.json;
const limit = parseInt(cfg.rateLimitMessagesPerMinute || '8', 10);
const windowMs = 60 * 1000;
const phone = $json.phone;
const now = Date.now();

const arr = (staticData.rateWindows[phone] || []).filter(ts => now - ts < windowMs);
arr.push(now);
staticData.rateWindows[phone] = arr;

const rateLimited = arr.length > limit;
return [{ json: { ...$json, rateLimited } }];

// Trust level is derived ONLY from backend data — never from user claims.
const parsed = $('Deduplication Check').item.json;
const lookup = $json.data || $json || {};
const contact = lookup.contact || {};

let mediaCtx = {};
try { mediaCtx = $('Normalize Media Context').item.json || {}; } catch (e) { mediaCtx = {}; }
if (!mediaCtx.mediaBlob && !mediaCtx.imageAnalysis && !mediaCtx.documentResult) {
  try { mediaCtx = $('Normalize Text Context').item.json || mediaCtx; } catch (e) {}
}

let actorType = 'unknown';
let trustLevel = 'L0';
let verified = false;

if (contact.driverVerified === true && contact.driverId) {
  actorType = 'driver';
  trustLevel = 'L3';
  verified = true;
} else if (contact.customerVerified === true && contact.customerId) {
  actorType = 'customer';
  trustLevel = 'L2';
  verified = true;
} else if (contact.id || contact.name) {
  actorType = 'unknown';
  trustLevel = 'L1';
  verified = false;
} else {
  actorType = 'unknown';
  trustLevel = 'L0';
  verified = false;
}

const imageAnalysis = String(mediaCtx.imageAnalysis || parsed.imageAnalysis || '');
const documentResult = String(mediaCtx.documentResult || parsed.documentResult || '');
const mediaBlob = String(mediaCtx.mediaBlob || imageAnalysis || documentResult || parsed.mediaBlob || '');
const inputType = String(mediaCtx.inputType || parsed.inputType || parsed.messageType || 'text');

return [{ json: {
  ...parsed,
  // Prefer OCR/combined text from Normalize Media Context (Lookup Contact drops these).
  inputType,
  text: mediaCtx.text || parsed.text,
  messageText: mediaCtx.messageText || parsed.messageText,
  imageAnalysis,
  documentResult,
  mediaBlob,
  mediaReadFailed: Boolean(mediaCtx.mediaReadFailed),
  mediaReadErrorReason: String(mediaCtx.mediaReadErrorReason || ''),
  actorType,
  trustLevel,
  verified,
  knownName: (contact.name || '').trim(),
  customerId: contact.customerId || null,
  driverId: contact.driverId || null,
  // Do NOT overwrite with contact.lastOrderReference — that re-caches the old order.
  contactRaw: contact
} }];

const staticData = $getWorkflowStaticData('global');
staticData.sessionsV4 = staticData.sessionsV4 || {};
const store = staticData.sessionsV4;
const cfg = $('Config').item.json || {};
const now = Date.now();
const timeoutMs = parseInt(cfg.sessionTimeoutMinutes || '30', 10) * 60 * 1000;
const phone = String($json.phone || '').trim();
const text = String($json.text || $json.messageText || '').trim();
let mediaBlob = String($json.imageAnalysis || $json.documentResult || $json.mediaBlob || '');
try {
  const n = $('Normalize Media Context').item.json || {};
  mediaBlob = mediaBlob || String(n.imageAnalysis || n.documentResult || n.mediaBlob || '');
  if (n.text) { /* keep caption+OCR text when trust node dropped fields */ }
} catch (e) {}

const STOP = new Set([
  'RIDER','DRIVER','DELIVERY','DELIVER','DELIVERING','PACKAGE','PARCEL','LOCKER','LOCATION','ADDRESS',
  'CUSTOMER','COLLECTION','COLLECT','PICKUP','OTP','CODE','PIN','ORDER','ORDERS','REFERENCE','REF',
  'TRACKING','NUMBER','STATUS','WHERE','WHAT','SEND','NEED','WANT','HELP','DETAILS','PLEASE','YES','NO',
  'OK','OKAY','HI','HELLO','HEY','THANKS','THANKYOU','LLBOX','NOON','AMAZON','JAHEZ','CAREEM'
]);

function normalizeRef(v) {
  return String(v || '').trim().replace(/[\u200B-\u200D\uFEFF]/g,'').replace(/[.,;:!?]+$/,'').toUpperCase();
}
function validRef(ref) {
  const r = normalizeRef(ref);
  const compact = r.replace(/[^A-Z0-9_-]/g,'');
  if (compact.length < 6 || compact.length > 48) return false;
  if (STOP.has(compact)) return false;
  if (/^(ORDER|ORD|REFERENCE|REF|TRACKING|NUMBER|LOCATION|ADDRESS|PACKAGE|PARCEL)[_-]?\d{0,5}$/i.test(compact)) return false;
  return /\d/.test(compact);
}
function extractOrderReference(value) {
  const s = String(value || '');
  if (!s) return '';
  const labeled = s.match(/\b(?:order|tracking|track|reference|ref|awb|shipment)\s*(?:id|number|no\.?|#|reference)?\s*[:#-]?\s*([A-Z0-9][A-Z0-9_-]{5,47})/i);
  if (labeled && validRef(labeled[1])) return normalizeRef(labeled[1]);
  const patterns = [
    /\bX360[-_][A-Z0-9_-]{4,47}\b/i,
    /\bOD\d{8,30}\b/i,
    /\bNSAI\d+[A-Z0-9_-]*\b/i,
    /\b(?:AMZ|AMZN)[-_]?[A-Z0-9][A-Z0-9_-]{5,47}\b/i,
    /\bN\d{8,30}\b/i,
    /\b\d{8,30}\b/,
    /\b[A-Z]{2,}[A-Z0-9_-]{3,47}\d[A-Z0-9_-]*\b/i,
    /\b[A-Z0-9]{3,}[-_][A-Z0-9_-]{3,47}\b/i
  ];
  for (const re of patterns) {
    const m=s.match(re); if(!m) continue;
    const r=normalizeRef(m[0]); if(validRef(r)) return r;
  }
  // Generic token fallback handles references such as "Abc123".
  for (const token of s.split(/\s+/)) {
    const r=normalizeRef(token);
    if (validRef(r) && /[A-Z]/i.test(r) && /\d/.test(r) && r.length >= 6) return r;
  }
  return '';
}

const foundOrder = extractOrderReference(text) || extractOrderReference(mediaBlob);
const existing = store[phone];
let session = existing && (now - Number(existing.lastActivity || 0) <= timeoutMs) ? existing : {
  sessionId: 'SESS-' + phone + '-' + now,
  createdAt: now,
  revision: 0,
  role: 'unknown',
  carrier: '',
  state: 'START',
  currentSubState: 'START',
  pendingIntent: '',
  lastIntent: '',
  lastBotAction: '',
  lastBotQuestion: '',
  orderReference: '',
  orderVerified: false,
  deliverySessionId: '',
  boxId: '',
  boxCode: '',
  address: '',
  googleMaps: '',
  otp: '',
  otpExpiresAt: '',
  otpSentCount: 0,
  otpAttempts: 0,
  completed: false,
  greeted: false,
  recentMessages: [],
  lastInboundMessageId: '',
  lastOutboundMessageId: '',
  lastActivity: now
};

function resetOrderSpecific() {
  session.orderVerified=false;
  session.deliverySessionId=''; session.boxId=''; session.boxCode='';
  session.address=''; session.googleMaps=''; session.otp=''; session.otpExpiresAt='';
  session.otpSentCount=0; session.otpAttempts=0; session.completed=false;
}

const lower=text.toLowerCase();
const wrongOrder=/\b(wrong order|not my (order|package)|isn'?t (my|mine)|wrong package)\b/i.test(text);
const newOrder=/\b(new order|different order|change order|another order)\b/i.test(text);
if (wrongOrder) {
  session.orderReference=''; resetOrderSpecific(); session.state='WAITING_FOR_ORDER'; session.currentSubState='NEED_ORDER_REF'; session.pendingIntent='';
}
if (foundOrder) {
  const prev=normalizeRef(session.orderReference);
  if (prev && prev !== foundOrder) resetOrderSpecific();
  session.orderReference=foundOrder;
  session.orderVerified=false;
  session.state='ORDER_RECEIVED';
  session.currentSubState='HAS_ORDER_REF';
}
if (newOrder && !foundOrder) {
  session.orderReference=''; resetOrderSpecific(); session.state='WAITING_FOR_ORDER'; session.currentSubState='NEED_ORDER_REF';
}

if (/\b(i am|i'?m|im)\s+(a\s+)?(driver|rider|delivery agent)\b|\b(driver|rider)\b/i.test(text)) session.role='driver';
if (/\b(i am|i'?m|im)\s+(the\s+)?(customer|recipient)\b|\b(collect|collection|pickup|pick up)\b/i.test(text)) session.role='customer';
if (/\b(noon|amazon|jahez|careem)\b/i.test(text)) session.carrier=(text.match(/\b(noon|amazon|jahez|careem)\b/i)||['',''])[1].toLowerCase();

session.recentMessages=Array.isArray(session.recentMessages)?session.recentMessages:[];
if (text || mediaBlob) {
  const inbound = { role:'user', text:(text || '[media] '+mediaBlob).slice(0,500), at:now, messageId:String($json.messageId||''), inputType:String($json.inputType||'text') };
  const last=session.recentMessages[session.recentMessages.length-1];
  if (!(last && last.role==='user' && last.messageId && last.messageId===inbound.messageId)) session.recentMessages.push(inbound);
  session.recentMessages=session.recentMessages.slice(-14);
}
session.lastInboundMessageId=String($json.messageId||'');
session.lastActivity=now;
session.correlationId=$json.correlationId;
session.actorType=$json.actorType || session.actorType || 'unknown';
session.trustLevel=$json.trustLevel || session.trustLevel || 'L0';
session.revision=Number(session.revision||0)+1;
store[phone]=session;

return [{ json:{ ...$json, session, lastOrderReference:session.orderReference||'', orderReferenceFound:foundOrder||'', state:session.state, conversationRevision:session.revision } }];

const staticData = $getWorkflowStaticData('global');
const kb = staticData.knowledge || null;
const cfg = $('Config').item.json;

const active = kb && kb.active ? kb.active : null;

return [{ json: { ...$json,
  knowledgeVersion: active ? active.version : 'none',
  knowledgeHash: active ? active.hash : null,
  knowledgeLastRefreshed: active ? active.fetchedAt : null,
  knowledgeContent: active ? active.content : '',
  knowledgeStale: active ? (Date.now() - active.fetchedAtMs) > (parseInt(cfg.knowledgeRefreshDays || '7', 10) * 24 * 60 * 60 * 1000 * 1.5) : true
} }];

const j=$json;
const s=j.session||{};
const recent=(s.recentMessages||[]).map(m=>`${m.role}: ${m.text}`).join('\n') || '(none)';
const allowed=['chat','resolve_delivery_access','request_collection_otp','confirm_delivery','clear_locker_session','human_escalation'];
const systemPrompt=`You are LLBox WhatsApp Assistant. You handle delivery riders and customers.

PRIMARY RULE: use CURRENT MESSAGE + CONVERSATION HISTORY + STATE. Never restart a conversation that is already in progress.

CURRENT STATE
role=${s.role||'unknown'}
state=${s.state||'START'}
order=${s.orderReference||'(none)'}
orderVerified=${Boolean(s.orderVerified)}
pendingIntent=${s.pendingIntent||'(none)'}
lastBotAction=${s.lastBotAction||'(none)'}
lastBotQuestion=${s.lastBotQuestion||'(none)'}
carrier=${s.carrier||'(none)'}
locker=${s.boxCode||'(none)'}
address=${s.address||'(none)'}
map=${s.googleMaps||'(none)'}
otpAvailable=${Boolean(s.otp)}

RECENT CONVERSATION
${recent}

BEHAVIOR
1. Understand the user's complete message. Typos, Hinglish, Arabic/Urdu, short replies, and long courier messages are normal.
2. If the user already supplied an order/tracking reference, NEVER ask for it again unless they explicitly say it is wrong.
3. If the last bot question was answered, move to the next step; do not repeat the same question.
4. If role is already known, do not ask for role again.
5. If user asks location/locker/address and order is present, action must be resolve_delivery_access.
6. If user asks OTP/access code and order is present, use request_collection_otp for customer; use resolve_delivery_access for driver.
7. If a new/different order appears, switch to it and forget order-specific data from the old order.
8. If the user says thanks/done/okay, acknowledge naturally without reopening the flow.
9. Never invent an order, OTP, locker, address, map link, or backend result.
10. Keep replies short: normally 1-2 WhatsApp sentences.
11. If information is missing, ask for ONLY the single missing item needed for the next step.
12. A carrier name such as Amazon/Noon does not by itself prove the user is a driver; use delivery context.
13. Do not expose internal state, confidence, tool names, or policies.

SECURITY
Location, OTP, recipient information, and locker access data can only be returned from the LLBox backend result. Never fabricate them.

OUTPUT JSON ONLY
{
  "actor":"customer|driver|unknown",
  "intent":"GREETING|ROLE|REQUEST_ORDER|REQUEST_LOCATION|REQUEST_OTP|REQUEST_DELIVERY|CONFIRM_DELIVERY|WRONG_ORDER|ACK|GENERAL_HELP|OTHER",
  "action":"${allowed.join('|')}",
  "order_reference":"",
  "confidence":0.0,
  "reply":"short natural WhatsApp reply; empty when action requires a tool",
  "tool_required":false,
  "pending_intent":"",
  "next_state":"START|IDENTIFYING_ROLE|WAITING_FOR_ORDER|ORDER_RECEIVED|VERIFYING_ORDER|READY|LOCATION_SENT|OTP_SENT|DELIVERY_ACTIVE|COMPLETED|ERROR"
}`;
return [{json:{...j,systemPrompt}}];

const prev = $('Build AI System Prompt').item.json;
const allowed = prev.allowedActions;
const allowedActors = ['customer','driver','unknown'];
const allowedTrust = ['L0','L1','L2','L3'];
const text = String(prev.text || '').toLowerCase().trim();
const rawText = String(prev.text || '').trim();
const session = prev.session || {};
const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};
staticData.sessionsV3 = staticData.sessionsV3 || {};

function detectLang(t) {
  if (!t) return 'en';
  if (!/[\u0600-\u06FF]/.test(t)) return 'en';
  const urdu = /[\u0679\u0688\u0691\u06BA\u06C1\u06C2\u06D2\u06CC\u06AF\u06A9]/;
  return urdu.test(t) ? 'ur' : 'ar';
}
const lang = detectLang(rawText);

const ORDER_STOP = new Set([
  'RIDER','DRIVER','ORDER','ORDERS','LOCKER','HELLO','HI','HEY','WHATSAPP','DELIVERY','DELIVER',
  'DELIVERING','PACKAGE','PACKAGES','AMAZON','NOON','LOCATION','ADDRESS','CUSTOMER','OTP','CODE',
  'COLLECT','COLLECTING','COLLECTION','PICKUP','PICK','YES','NO','OK','OKAY','THANKS','THANKYOU',
  'AGENT','PLEASE','HELP','DETAILS','REFERENCE','TRACKING','NUMBER','STATUS','WHERE','WHAT',
  'SEND','NEED','WANT','PACKAGE','PARCEL','BOX','LLBOX'
]);

const extractOrder = (value) => {
  const s = String(value || '').trim();
  if (!s) return '';
  const ocrLine = s.match(/order_reference:\s*([A-Z0-9][A-Z0-9_-]{5,})/i);
  if (ocrLine) {
    const ref = ocrLine[1].toUpperCase();
    const compact = ref.replace(/[^A-Z0-9]/g, '');
    if (compact.length >= 8 && /[0-9]/.test(compact)) return ref;
  }
  const labelMatch = s.match(/\border[\s_-]*(?:id|ref(?:erence)?|number|no)[:\s#-]+([A-Z0-9][A-Z0-9_-]{5,})/i);
  if (labelMatch) {
    const fromLabel = labelMatch[1].toUpperCase();
    if (/^\d{6,22}$/.test(fromLabel) || /^X360/i.test(fromLabel) || /^(ORDER|ORD|AMZ|OD|NSAI)/i.test(fromLabel)) {
      return fromLabel;
    }
  }
  const patterns = [
    /X360[-_][A-Z0-9-]{6,}/i,
    /\bOD\d{10,}\b/i,
    /\bNSAI\d+[A-Z0-9_-]*/i,
    /\b(?:ORDER|ORD)[-_][A-Z0-9]+(?:[-_][A-Z0-9]+)*/i,
    /\b(?:AMZ|AMZN)[-_]?[A-Z0-9]+(?:[-_][A-Z0-9]+)*/i,
    /\bN\d{8,}\b/i,
    /\b\d{6,22}\b/,
    /\b[A-Z]{2,}\d[-A-Z0-9]{5,}\b/i,
    /\b[A-Z0-9]{3,}[-_][A-Z0-9]+(?:[-_][A-Z0-9]+)*/i
  ];
  for (const re of patterns) {
    const m = s.match(re);
    if (!m) continue;
    const ref = m[0].toUpperCase();
    const compact = ref.replace(/[^A-Z0-9]/g, '');
    if (ORDER_STOP.has(compact) || compact.length < 6) continue;
    if (/^ORDERREFERENCE$/i.test(compact) || /^ORDERID$/i.test(compact)) continue;
    if (!/[0-9]/.test(compact) && !/[-_]/.test(ref)) continue;
    if (/^(ORDER|ORD|AMZ|AMZN)[-_][A-Z]+$/.test(ref) && !/[0-9]/.test(ref)) continue;
    if (!/^X360/i.test(ref) && !/[0-9]/.test(compact)) continue;
    return ref;
  }
  return '';
};

const isValidOrderRef = (ref) => {
  if (!ref) return false;
  const u = String(ref).toUpperCase();
  const compact = u.replace(/[^A-Z0-9]/g, '');
  if (ORDER_STOP.has(compact)) return false;
  if (compact.length < 6) return false;
  if (/^(ORDER|ORD|AMZ|AMZN)[-_][A-Z]+$/.test(u) && !/[0-9]/.test(u)) return false;
  if (!/^X360/i.test(u) && !/[0-9]/.test(compact)) return false;
  return true;
};

const mediaBlob = String(prev.imageAnalysis || prev.documentResult || prev.mediaBlob || '');
let ocrExtra = '';
try {
  const n = $('Normalize Media Context').item.json || {};
  ocrExtra = String(n.imageAnalysis || n.documentResult || n.mediaBlob || '');
} catch (e) { ocrExtra = ''; }
const ocrText = mediaBlob || ocrExtra;
const isMediaUpload = ['image','document','audio'].includes(String(prev.inputType || ''));
const hasMediaData = Boolean(ocrText);
const orderFromMedia = extractOrder(ocrText);
const orderFromText = extractOrder(rawText);
const orderFromMsg = orderFromText || orderFromMedia;
// New invoice/photo OR a newly typed order ID must replace the cached session order.
let orderRef = '';
if (isMediaUpload) {
  orderRef = orderFromMedia || orderFromText || '';
} else if (orderFromText) {
  // Rider typed a new tracking/order ID — always switch (multi-drop same box).
  orderRef = orderFromText;
} else {
  orderRef = prev.lastOrderReference || session.orderReference || '';
}
if (!isValidOrderRef(orderRef)) orderRef = '';

// When switching to a different order, wipe prior locker/OTP cache so we do not reuse A for B.
const prevOrder = String(session.orderReference || prev.lastOrderReference || '').toUpperCase();
if (orderRef && prevOrder && orderRef !== prevOrder) {
  try {
    const phoneKey = prev.phone;
    const sSwitch = staticData.sessions[phoneKey] || {};
    const s3Switch = staticData.sessionsV3[phoneKey] || {};
    for (const store of [sSwitch, s3Switch, session]) {
      store.deliverySessionId = '';
      store.boxId = '';
      store.boxCode = '';
      store.address = '';
      store.googleMaps = '';
      store.otp = '';
      store.otpExpiresAt = '';
      store.locationSent = false;
      store.otpSent = false;
      store.orderReference = orderRef;
      store.currentSubState = 'HAS_ORDER_REF';
    }
    if (phoneKey) {
      staticData.sessions[phoneKey] = { ...(staticData.sessions[phoneKey] || {}), ...sSwitch };
      staticData.sessionsV3[phoneKey] = { ...(staticData.sessionsV3[phoneKey] || {}), ...s3Switch };
    }
  } catch (e) {}
}

// --- Intent flags: declare ALL before any use (fixes TDZ / wantsOtp error) ---
const isGreetingOnly = /^(hi+|hello|hey+|salam|assalam|marhaba|good morning|good evening)[.!\s]*$/i.test(rawText);
const startsWithHi = /^(hi+|hello|hey+|salam|assalam|marhaba)\b/i.test(rawText);
const isGreeting = isGreetingOnly;
